### Python

```python
import sys
from math import isqrt

LIMIT = 10 ** 6

def get_primes():
    # 埃氏筛预处理纯净数
    is_prime = [True] * (LIMIT + 1)
    is_prime[0] = is_prime[1] = False

    for i in range(2, isqrt(LIMIT) + 1):
        if is_prime[i]:
            for j in range(i * i, LIMIT + 1, i):
                is_prime[j] = False

    primes = []
    for i in range(2, LIMIT + 1):
        if is_prime[i]:
            primes.append(i)
    return primes

PRIMES = get_primes()

def check_prime(x):
    # 判断 x 是否为纯净数，这里 x 最大不超过 10^9
    if x < 2:
        return False
    for p in PRIMES:
        if p * p > x:
            break
        if x % p == 0:
            return False
    return True

def solve_one(n):
    ans = []
    x = n

    # 处理所有不超过 10^6 的纯净因子
    for p in PRIMES:
        if p * p > x:
            break

        cnt = 0
        while x % p == 0:
            x //= p
            cnt += 1

        # 如果 p 至少出现 2 次，则 p^2 是答案
        if cnt >= 2:
            ans.append(p * p)

    # 剩余部分可能是一个大纯净数的平方
    r = isqrt(x)
    if r * r == x and check_prime(r):
        ans.append(x)

    return ans

def main():
    data = sys.stdin.read().strip().split()
    t = int(data[0])
    res = []

    for i in range(1, t + 1):
        n = int(data[i])
        ans = solve_one(n)

        if ans:
            res.append(" ".join(map(str, ans)))
        else:
            res.append("-1")

    print("\n".join(res))

if __name__ == "__main__":
    main()
```

